{"implementation": "def solve(case):
    # Build lookup maps
    nodes = list(case['nodes'])
    required_symbols = set(case['required_symbols'])
    node_map = {node['id']: node for node in nodes}
    children = {node['id']: [] for node in nodes}
    for node in nodes:
        pid = node.get('parent')
        if pid is not None:
            children[pid].append(node['id'])
    # Initial retained set includes all nodes
    retained = set(node_map.keys())
    # Gather candidates: removable, not root, symbol not required
    candidates = []
    for node in nodes:
        if node['removable'] and node['id'] != 'root' and node['symbol'] not in required_symbols:
            candidates.append(node['id'])
    # Sort by depth descending, then by id ascending for stable tiebreak
    candidates.sort(key=lambda nid: (-node_map[nid]['depth'], nid))
    # Precompute symbol -> set of node ids for required-symbol checks
    symbol_ids = {}
    for node in nodes:
        sym = node['symbol']
        symbol_ids.setdefault(sym, set()).add(node['id'])
    removed = []
    for nid in candidates:
        if nid not in retained:
            continue
        # Node must have no retained children
        has_retained_children = any(c in retained for c in children[nid])
        if has_retained_children:
            continue
        # Tentatively remove: check required symbols still present
        temp_retained = retained - {nid}
        ok = True
        for req in required_symbols:
            # Check if any node with that symbol remains in retained set
            ids_with_symbol = symbol_ids.get(req, set())
            if not ids_with_symbol.intersection(temp_retained):
                ok = False
                break
        if ok:
            retained = temp_retained
            removed.append(nid)
    # Sort retained node ids alphabetically
    retained_sorted = sorted(retained)
    return {'removed_node_ids': removed, 'retained_node_ids': retained_sorted}"}
